<?php require_once __DIR__.'/../config/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare('UPDATE certificates SET status="revoked" WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Certificado revogado.');redirect('admin/certificados.php');}$rows=db()->query('SELECT ce.*,u.nome,c.titulo FROM certificates ce JOIN users u ON u.id=ce.user_id JOIN courses c ON c.id=ce.course_id ORDER BY ce.issued_at DESC')->fetchAll(); ?>
<?php layout_header('Certificados'); ?><div class="dash-head"><div><span class="eyebrow">ADMIN</span><h1>Certificados</h1></div></div><div class="table-wrap"><table><thead><tr><th>Código</th><th>Aluno</th><th>Curso</th><th>Emissão</th><th>Validade</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><code><?=e($r['codigo'])?></code></td><td><?=e($r['nome'])?></td><td><?=e($r['titulo'])?></td><td><?=e(date('d/m/Y',strtotime($r['issued_at'])))?></td><td><?=e(date('d/m/Y',strtotime($r['validade'])))?></td><td><span class="badge <?=$r['status']?>"><?=e($r['status'])?></span></td><td><?php if($r['status']==='active'): ?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="mini-btn danger">Revogar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php layout_footer(); ?>
